 static double clearance(Object level,Object player,Object eye,double yaw,double pitch,double length){double[] b=Rules.behind(yaw,pitch,length);Object dest=plus(eye,b[0],b[1],b[2]);double minimum=1;for(double[] offset:new double[][]{{0,0,0},{.25,0,0},{-.25,0,0},{0,.25,0},{0,-.25,0}}){Object a=plus(eye,offset[0],offset[1],offset[2]),end=plus(dest,offset[0],offset[1],offset[2]);Object hit=clip(level,player,a,end);minimum=Math.min(minimum,distance(a,R.call(hit,"getLocation"))/length);}return minimum;}
 public static void finishCamera(Object camera){try{if(!active())return;Object mc=mc(),player=R.get(mc,"player"),level=R.get(mc,"level");if(player==null||level==null)return;Object eye=R.call(player,"getEyePosition"),pos=R.call(camera,"getPosition");double d=distance(eye,pos);if(d<0.01)return;double fraction=1;for(double[] offset:new double[][]{{0,0,0},{.2,0,0},{-.2,0,0},{0,.2,0},{0,-.2,0}}){Object a=plus(eye,offset[0],offset[1],offset[2]),b=plus(pos,offset[0],offset[1],offset[2]);Object collision=clip(level,player,a,b);if(R.call(collision,"getType").toString().equals("BLOCK"))fraction=Math.min(fraction,Math.max(0,(distance(a,R.call(collision,"getLocation"))-.3)/d));}long now=System.nanoTime();double safe=d*fraction;if(cameraDistance>0&&safe>cameraDistance)safe=Math.min(safe,cameraDistance+6*Math.min(.05,(now-lastCollisionFrame)/1e9));cameraDistance=safe;lastCollisionFrame=now;fraction=safe/d;if(fraction<.999)R.call(camera,"setPosition",vec(v(eye,"x")+(v(pos,"x")-v(eye,"x"))*fraction,v(eye,"y")+(v(pos,"y")-v(eye,"y"))*fraction,v(eye,"z")+(v(pos,"z")-v(eye,"z"))*fraction));}catch(Throwable e){warn("camera collision",e);}}
 public static boolean suppressNativeLook(Object entity){try{return active()&&entity==R.get(mc(),"player")&&gun(entity);}catch(Throwable e){warn("native look compatibility",e);return false;}}
 public static void aim(){try{Object mc=mc(),player=R.get(mc,"player");if(!active()||player==null||R.get(mc,"screen")!=null||!gun(player)){aimed=false;return;}Object hit=R.get(mod(),"crosshairTarget");if(hit==null)return;Object target=R.call(hit,"getLocation"),eye=R.call(player,"getEyePosition");double dx=v(target,"x")-v(eye,"x"),dy=v(target,"y")-v(eye,"y"),dz=v(target,"z")-v(eye,"z");if(dx*dx+dy*dy+dz*dz<.04)return;double[] a=Rules.angles(dx,dy,dz);double yaw=a[0],pitch=a[1];if(aimed&&aimPlayer==player){yaw=R.num(R.call(player,"getYRot"))+Rules.wrap(yaw-lastDesiredYaw);pitch=R.num(R.call(player,"getXRot"))+(pitch-lastDesiredPitch);}R.set(mod(),"livingPitch",(float)R.num(R.call(player,"getXRot")));R.set(mod(),"livingYaw",(float)R.num(R.call(player,"getYRot")));R.set(mod(),"livingHeadYaw",(float)R.num(R.call(player,"getYHeadRot")));R.set(mod(),"livingBodyYaw",(float)R.num(R.get(player,"yBodyRot")));lastDesiredYaw=a[0];lastDesiredPitch=a[1];aimed=true;aimPlayer=player;R.call(player,"setYRot",(float)yaw);R.call(player,"setYHeadRot",(float)yaw);R.set(player,"yBodyRot",(float)yaw);R.call(player,"setXRot",(float)Math.max(-89.9,Math.min(89.9,pitch)));}catch(Throwable e){warn("gun aim",e);}}
 public static void cancelScope(Object callback){try{if(active())R.call(callback,"cancel");}catch(Throwable e){warn("scope FOV",e);}}
 public static void captureProjection(Object matrix){try{projection=R.make("org.joml.Matrix4f",matrix);}catch(Throwable e){warn("projection capture",e);}}
 public static boolean sprintOverride(Object owner,Object callback){try{Object mc=mc(),player=R.get(mc,"player");if(!active()||player==null||R.get(mc,"screen")!=null)return false;Object input=R.get(player,"input");if(owner!=input&&owner!=player)return false;boolean moving=Rules.sprint(R.num(R.get(input,"forwardImpulse")),R.num(R.get(input,"leftImpulse")));R.call(callback,"setReturnValue",Boolean.valueOf(moving));return true;}catch(Throwable e){warn("free sprint",e);return false;}}
 public static void render(Object graphics){try{Object mc=mc(),player=R.get(mc,"player");if(!active()||projection==null||player==null||R.get(mc,"screen")!=null||R.yes(R.get(R.get(mc,"options"),"hideGui"))||!gun(player))return;Object eye=R.call(player,"getEyePosition"),direction=R.call(player,"getViewVector",1f),end=plus(eye,v(direction,"x")*128,v(direction,"y")*128,v(direction,"z")*128),level=R.get(mc,"level");Object point=R.call(clip(level,player,eye,end),"getLocation");double best=distance(eye,point);Object box=R.call(R.call(player,"getBoundingBox"),"expandTowards",R.call(direction,"scale",128d));box=R.call(box,"inflate",1d);java.util.function.Predicate<Object> pick=e->R.yes(R.call(e,"isPickable"))&&!R.yes(R.call(e,"isSpectator"));for(Object entity:(List<?>)R.call(level,"getEntities",player,box,pick)){Object bounds=R.call(R.call(entity,"getBoundingBox"),"inflate",(double)((Number)R.call(entity,"getPickRadius")).floatValue());Optional<?> intersection=(Optional<?>)R.call(bounds,"clip",eye,end);if(intersection.isPresent()&&distance(eye,intersection.get())<best){point=intersection.get();best=distance(eye,point);}}
  Object camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera"),pos=R.call(camera,"getPosition"),q=R.make("org.joml.Quaternionf",R.call(camera,"rotation"));R.call(q,"conjugate");Object relative=R.make("org.joml.Vector3f",(float)(v(point,"x")-v(pos,"x")),(float)(v(point,"y")-v(pos,"y")),(float)(v(point,"z")-v(pos,"z")));R.call(q,"transform",relative);Object clip=R.make("org.joml.Vector4f",(float)v(relative,"x"),(float)v(relative,"y"),(float)v(relative,"z"),1f);R.call(projection,"transform",clip);double[] screen=Rules.project(v(clip,"x"),v(clip,"y"),v(clip,"w"),((Number)R.call(graphics,"guiWidth")).intValue(),((Number)R.call(graphics,"guiHeight")).intValue());if(screen==null)return;draw(graphics,(int)Math.round(screen[0]),(int)Math.round(screen[1]));
 }catch(Throwable e){warn("third person crosshair",e);}}
 static boolean corpse(Object entity){return entity!=null&&entity.getClass().getName().equals("de.maxhenkel.corpse.entities.CorpseEntity");}
 static boolean remains(String id){return id.startsWith("doomsday_decoration:remains_")||id.equals("zombie_remains_loot:skeletal_remains");}
 static String blockId(Object state){Object registry=R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"BLOCK");return R.call(registry,"getKey",R.call(state,"getBlock")).toString();}
 static double blockDistance(Object eye,Object pos){double dx=Math.max(0,Math.max(R.coord(pos,"X")-v(eye,"x"),v(eye,"x")-R.coord(pos,"X")-1)),dy=Math.max(0,Math.max(R.coord(pos,"Y")-v(eye,"y"),v(eye,"y")-R.coord(pos,"Y")-1)),dz=Math.max(0,Math.max(R.coord(pos,"Z")-v(eye,"z"),v(eye,"z")-R.coord(pos,"Z")-1));return Math.sqrt(dx*dx+dy*dy+dz*dz);}
 static boolean interactable(Object mc,Object hit){if(hit==null)return false;Object player=R.get(mc,"player"),level=R.get(mc,"level"),eye=R.call(player,"getEyePosition"),point=R.call(hit,"getLocation");String kind=R.call(hit,"getType").toString();Object pos=null;
  if(kind.equals("BLOCK")){pos=R.call(hit,"getBlockPos");Object state=R.call(level,"getBlockState",pos);if(!remains(blockId(state))&&!R.yes(R.call(R.type("com.cleannrooster.dungeons_iso.util.InteractionTargeting"),"isInteractable",level,pos)))return false;if(blockDistance(eye,pos)>R.num(R.call(player,"blockInteractionRange")))return false;
  }else if(kind.equals("ENTITY")){Object entity=R.call(hit,"getEntity");if(!corpse(entity)||!R.yes(R.call(player,"canInteractWithEntity",entity,0d)))return false;}else return false;
  Object obstruction=clip(level,player,eye,point);return !R.call(obstruction,"getType").toString().equals("BLOCK")||pos!=null&&pos.equals(R.call(obstruction,"getBlockPos"))||distance(eye,R.call(obstruction,"getLocation"))>=distance(eye,point)-.05;
 }
 static Object cursorCorpse(Object mc){if(projection==null)return null;Object window=R.call(mc,"getWindow"),mouse=R.get(mc,"mouseHandler"),camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera");double nx=2*R.num(R.call(mouse,"xpos"))/R.num(R.call(window,"getWidth"))-1,ny=1-2*R.num(R.call(mouse,"ypos"))/R.num(R.call(window,"getHeight"));Object inv=R.make("org.joml.Matrix4f",projection);R.call(inv,"invert");Object near=R.make("org.joml.Vector4f",(float)nx,(float)ny,-1f,1f),far=R.make("org.joml.Vector4f",(float)nx,(float)ny,1f,1f);R.call(inv,"transform",near);R.call(inv,"transform",far);Object q=R.call(camera,"rotation"),pos=R.call(camera,"getPosition");Object[] points=new Object[2];int i=0;for(Object p:new Object[]{near,far}){double w=v(p,"w");if(Math.abs(w)<1e-6)return null;Object vector=R.make("org.joml.Vector3f",(float)(v(p,"x")/w),(float)(v(p,"y")/w),(float)(v(p,"z")/w));R.call(q,"transform",vector);points[i++]=plus(pos,v(vector,"x"),v(vector,"y"),v(vector,"z"));}
  Object start=points[0],direction=R.call(R.call(points[1],"subtract",start),"normalize"),end=R.call(start,"add",R.call(direction,"scale",128d)),player=R.get(mc,"player"),level=R.get(mc,"level");Object box=R.call(R.type("net.minecraft.world.phys.AABB"),"ofSize",start,1d,1d,1d);box=R.call(R.call(box,"expandTowards",R.call(direction,"scale",128d)),"inflate",.3d);java.util.function.Predicate<Object> filter=Bridge::corpse;Object closest=null;double best=128;for(Object entity:(List<?>)R.call(level,"getEntities",player,box,filter)){Optional<?> point=(Optional<?>)R.call(R.call(R.call(entity,"getBoundingBox"),"inflate",.15d),"clip",start,end);if(point.isEmpty())continue;double d=distance(start,point.get());if(d>=best)continue;Object hit=R.make("net.minecraft.world.phys.EntityHitResult",entity,point.get());if(interactable(mc,hit)){best=d;closest=hit;}}return closest;
 }
 static boolean mouseClaimed;
 public static void mouse(long window,int button,int action,int modifiers,Object callback){try{Object mc=mc();if(button!=1||window!=((Number)R.call(R.call(mc,"getWindow"),"getWindow")).longValue())return;if(action==0&&mouseClaimed){mouseClaimed=false;if(R.get(mc,"screen")==null)R.call(callback,"cancel");return;}if(action!=1||!active()||R.get(mc,"screen")!=null||R.get(mc,"player")==null||R.get(mc,"level")==null)return;Object hit=R.get(mod(),"crosshairTarget");if(!interactable(mc,hit))hit=cursorCorpse(mc);if(hit==null||!interactable(mc,hit))return;
  R.call(callback,"cancel");mouseClaimed=true;Object player=R.get(mc,"player"),game=R.get(mc,"gameMode"),hand=R.get(R.type("net.minecraft.world.InteractionHand"),"MAIN_HAND");R.set(mc,"hitResult",hit);R.set(mc,"crosshairPickEntity",R.call(hit,"getType").toString().equals("ENTITY")?R.call(hit,"getEntity"):null);Object result=R.call(hit,"getType").toString().equals("BLOCK")?R.call(game,"useItemOn",player,hand,hit):R.call(game,"interact",player,R.call(hit,"getEntity"),hand);if(R.yes(R.call(result,"shouldSwing")))R.call(player,"swing",hand);
 }catch(Throwable e){warn("right click interaction",e);}}
 static void draw(Object g,int x,int y){int c=0xFFF2E7C5;R.call(g,"fill",x-8,y-1,x-3,y+1,c);R.call(g,"fill",x+3,y-1,x+8,y+1,c);R.call(g,"fill",x-1,y-8,x+1,y-3,c);R.call(g,"fill",x-1,y+3,x+1,y+8,c);R.call(g,"fill",x-1,y-1,x+1,y+1,0xFFE3AB4F);}
